pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 amount = 10 + (seed % 50); // wide domain around the ticket price
        vm.deal(actor, amount);

        uint256 potBefore = c.pot();
        vm.prank(actor);
        try c.play{value: amount}() {
            // rule: a successful play must credit the pot with the ether actually sent
            assertTrue(c.pot() == potBefore + amount, "pot must grow by the sent value");
        } catch {
            // rule: a rejected play must leave the pot untouched and the contract balance unchanged
            assertTrue(c.pot() == potBefore && address(c).balance == potBefore, "failed play must not change state");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint128).max);

        // snapshot pot before the call
        uint256 prePot = c.pot();

        // give the caller exactly `amount` wei and drive c through play
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // The call succeeded, so amount must have been the ticket price.
            // Rule: the pot after a non-winning play equals the pre-call pot plus
            // the ether ACTUALLY sent in this call; a winning play resets it to 0
            // after paying out (prePot + msg.value - FEE to the player, FEE to bank),
            // so the contract's balance can never fall below the pot it owes.
            assertTrue(
                (c.pot() == 0 && address(c).balance >= 0)
                    || c.pot() == prePot + amount,
                "pot must track the ether actually sent (or be fully paid out)"
            );
        } else {
            // A failed call must leave state untouched.
            assertTrue(
                c.pot() == prePot,
                "reverted play must not change pot"
            );
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 seed) public {
        // keep the domain WIDE: any value and any seed are admissible
        value = bound(value, 0, type(uint128).max);
        address actor = address(uint160(bound(uint256(uint160(msg.sender)) + seed, 1, type(uint160).max)));
        if (value > actor.balance) vm.deal(actor, value);

        // control the pseudo-random branch: choose warp/roll from the fuzzed seed
        uint256 slot = seed % 100;
        uint256 ts = 1_000_000 + (seed / 100) % 1000;
        vm.roll(slot);
        vm.warp(ts);

        uint256 potBefore = c.pot();
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.play{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // recompute whether this call hit the win branch under the same slot/timestamp
            uint256 random = uint(keccak256(abi.encodePacked(ts, slot))) % 2;
            if (random != 0) {
                // losing play: pot must have grown by exactly the ether actually sent
                assertTrue(c.pot() == potBefore + value && address(c).balance == balBefore + value);
            } else {
                // winning play: pot fully paid out and reset to zero
                assertTrue(c.pot() == 0 && address(c).balance == balBefore + value - (potBefore + value) && (balBefore + value) - address(c).balance == 0 || c.pot() == 0);
            }
        } else {
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= amount);
        bool ok;
        (ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.play.selector));
        assert(ok || c.pot() != 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amt) public {
        require(address(this).balance >= 2 * amt);

        c.play{value: amt}();
        uint b1 = address(this).balance;

        c.play{value: amt}();
        uint b2 = address(this).balance;

        assert(b2 != b1 - 1 || c.pot() == 0);
    }
}

