contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        uint before = c.pot();
        c.play{value: amount}();
        assert(c.pot() == 0 || c.pot() == before + amount);
    }
    receive() external payable {}
